get_search_settings.code:
import {searchSettings} from 'webcommander-sdk';

const response = await searchSettings.getSearchSettings(client);
const settings = response.map.search_settings;
console.log(settings.searchable_content.placeholder_text, settings.searchable_content.product.enabled);
console.log(settings.search_fields.match_keywords_exactly, settings.search_fields.fields.length);
console.log(settings.synonyms.groups.length);

patch_search_settings.code:
import {searchSettings} from 'webcommander-sdk';

const response = await searchSettings.patchSearchSettings(client, {
    search_settings: {
        searchable_content: {placeholder_text: 'Search products'},
        search_fields: {match_keywords_exactly: true},
    },
});
const settings = response.map.search_settings;
console.log(settings.searchable_content.placeholder_text, settings.search_fields.match_keywords_exactly);

put_search_settings.code:
import {searchSettings} from 'webcommander-sdk';

const response = await searchSettings.putSearchSettings(client, {
    search_settings: {
        searchable_content: {
            placeholder_text: 'Search products',
            product: {enabled: true, display_heading: 'Product', excluded: [{id: 4, name: 'Gift Card'}]},
            product_categories: {
                enabled: true,
                hide_parent_category: true,
                display_heading: 'Product Categories',
                excluded: [{id: 16, name: 'Clearance'}],
            },
            blog: {enabled: true, display_heading: 'Blog Posts', excluded: [{id: 13, name: 'Store News'}]},
            other_pages: {enabled: true, display_heading: 'Other Pages', excluded: [{id: 4, name: 'Home - Copy'}]},
        },
        search_fields: {
            match_keywords_exactly: false,
            match_full_sentences: false,
            fields: [
                {field: 'title', priority: 1},
                {field: 'tags', priority: 2},
                {field: 'category', priority: 3},
                {field: 'description', priority: 4},
                {field: 'sku', priority: 5},
                {field: 'brand', priority: 6},
            ],
        },
        synonyms: {groups: [{keywords: ['mobile', 'phone', 'telephone']}, {keywords: ['shoe', 'footwear', 'sneaker']}]},
    },
});
const settings = response.map.search_settings;
console.log(settings.searchable_content.placeholder_text, settings.search_fields.fields.length);

